head.script:
scwin.onpageload = function() {
	requires("uiplugin.popup");
};
scwin.trigger1_onclick = function(e) {
	var options={
		id: ""
		, type: "wframePopup"
		, width: "400px"
		, height: "400px"
		, top: e.clientY
		, left: e.clientX
		, modal: true
		, useModalStack: true
	};
	$p.openPopup("/sample/common_link/p_wframePopup_gridView_WAEA-702_(WSQ-6264)_main_sub.xml", options);
};
